    @GET("api/books/{id}/cover")
    suspend fun getCover(
        @Path("id") id: String,
    ): ResponseBody

    @GET("api/books/{id}/exports")
    suspend fun listExports(
        @Path("id") id: String,
    ): List<BookExportDto>

    /**
     * handleCreateExport queues an export as a job-queue task (a Jobs-page
     * row, Kind "pipeline_export") - rebuilding it if one with the same
     * settings already exists. Unless AsIs, the task first renders the
     * chapters' missing audio (jobs.Manager.RenderChapters) and waits for it.
     * Progress and the result show up on the bookExports live topic.
     */
    @POST("api/books/{id}/exports")
    suspend fun createExport(
        @Path("id") id: String,
        @Body body: CreateExportRequestDto,
    ): QueuedResponseDto

    /**
     * handleDeleteExport removes an export's file, or cancels its task.
     */
    @DELETE("api/books/{id}/exports/{exportId}")
    suspend fun deleteExport(
        @Path("id") id: String,
        @Path("exportId") exportId: String,
    ): Unit

    @Streaming
    @GET("api/books/{id}/exports/{exportId}/file")
    suspend fun getExportFile(
        @Path("id") id: String,
        @Path("exportId") exportId: String,
    ): ResponseBody

    /**
     * handleGenerateBook enqueues background TTS generation for every chapter
     * in a book at once - the library page's own "Generate audio" -> "All"
     * button (LibraryPage.tsx), for a reader who wants a whole book ready to
     * listen to without opening it chapter by chapter first.
     *
     * A single call into jobs.Manager.EnqueueBookGenerate, not a loop over
     * every chapter here: that whole-book walk (and its own cancelability) now
     * lives on the Manager side, as one cancelable poolPipeline task rather
     * than this handler pushing N independent per-chapter tasks with no
     * single handle to stop them all at once - see EnqueueBookGenerate's own
     * doc comment. Fire-and-forget either way: this never itself blocks on an
     * actual TTS render or LLM call the way a preprocessing phase does, and
     * calling it twice in a row, or alongside a reader actively reading the
     * book, just re-enqueues whatever isn't already ready/generating,
     * harmlessly (EnqueueBookGenerate's own task is idempotent per book, same
     * as EnqueueChapter always was per chapter).
     */
    @POST("api/books/{id}/generate")
    suspend fun generateBook(
        @Path("id") id: String,
    ): QueuedResponseDto

    /**
     * handleGenerateRemaining enqueues background TTS generation for every
     * paragraph in a book from its current stored reading position
     * (store.Book.PosChapterIdx/PosParagraphIdx) through the end of the book -
     * the "Remaining" option on the library page's "Generate audio" button
     * (LibraryPage.tsx), alongside handleGenerateBook's "All" option. Position
     * is read server-side rather than taken from the request body: it's the
     * same value GET /api/books already returns per book, so a caller (the
     * library page, or the Android app's own long-press equivalent) needs
     * nothing beyond the book ID to mean "the rest of this book, from wherever
     * I've actually gotten to". See jobs.Manager.EnqueueRemaining.
     */
    @POST("api/books/{id}/generate-remaining")
    suspend fun generateRemaining(
        @Path("id") id: String,
    ): QueuedResponseDto

    /**
     * handleLookahead keeps some runway of generated audio ahead of wherever
     * the reader currently is, spanning into later chapters as needed rather
     * than stopping at the current chapter's end - see
     * jobs.Manager.EnqueueLookahead.
     */
    @POST("api/books/{id}/lookahead")
    suspend fun lookahead(
        @Path("id") id: String,
        @Body body: LookaheadRequestDto,
    ): QueuedResponseDto

    /**
     * handleBookManifest returns a book's offline-sync root hash plus its
     * chapter hashes. `?chapters=0,3,7` limits it to those chapters (unknown
     * indexes are just absent from the result) - a client only ever holds a
     * few chapters of a book offline, so it asks for just what it has; the
     * root then covers only that subset, which is still exactly what it needs
     * to compare against. Without the parameter, every chapter is included.
     *
     * Chapter hashes come from the stored tree (store.SyncTreeNodes) wherever
     * their inputs haven't moved, so an unchanged book costs a fingerprint
     * query plus two small reads, not a buildChapter per chapter - see "The
     * stored tree" above.
     */
    @GET("api/books/{id}/manifest")
    suspend fun bookManifest(
        @Path("id") id: String,
        @Query("chapters") chapters: String? = null,
    ): BookManifestDto

    @GET("api/books/{id}/position")
    suspend fun getPosition(
        @Path("id") id: String,
    ): PositionDto

    @PUT("api/books/{id}/position")
    suspend fun updatePosition(
        @Path("id") id: String,
        @Body body: PositionDto,
    ): Unit

    /**
     * handlePreprocessBook kicks off the preprocessing pipeline for the whole
     * book (see jobs.Manager.EnqueuePipeline) and returns
     * immediately (202) - the same fire-and-forget shape as
     * handleAttributeSpeakers/handleTagDirections, for the same reason: a
     * whole book can take anywhere from minutes to hours to fully attribute/
     * characterize/provision/tag, so nothing should hold an HTTP request (or a
     * browser connection) open for it. Progress is observable the same way
     * running each phase's own buttons individually already is - via GET
     * /api/jobs (each chapter/character's own attribution/characterization/
     * direction/provision task appears there as it's dispatched, same Kinds
     * as the single-item buttons use), by refetching the book's speaker table
     * as chapters/characters complete, and via bookSummaryDTO.Preprocessing
     * (see isPreprocessing) for a simple whole-book "still running" indicator
     * - the library page polls this to show a spinner over the cover for as
     * long as it's true.
     *
     * Rejects (409) a second call for a book that already has one of these
     * running - see jobs.ErrPipelineAlreadyRunning.
     *
     * chapters is listed once here, before any phase is even enqueued, and
     * shared unchanged by every chapter-scoped phase below (see their own doc comments for why that
     * staleness is safe) - mirroring the one piece of shared, hoisted state
     * the old single-goroutine runBookPipeline used to keep across its own
     * four inline phases; a failure listing it aborts the whole preprocessing
     * request up front (500) rather than starting phase 1 with nothing to do.
     */
    @POST("api/books/{id}/preprocess")
    suspend fun preprocessBook(
        @Path("id") id: String,
    ): QueuedResponseDto

    /**
     * handleResetPass is POST /api/books/{id}/reset/{pass} - the Speakers
     * page's per-column reset buttons: clears one pass across the whole book as
     * though it had never run, and deletes whatever generated audio it made
     * stale. pass is a bulk action name:
     *   - "attribution"/"description"/"scare_quote"/"direction"/"pronunciation":
     *     the paragraph data that pass wrote plus its chapters.passes flag (see
     *     store.PassResets), invalidating audio for just the paragraphs whose
     *     narration it changed (and their scare-quote merge groups). The
     *     character roster is left alone - "Delete speaker data" covers that.
     *   - "music_scoring": every music region (and its clip), unsetting
     *     passes.music
     *   - "music_generation": every music region's clip, back to pending
     *   - "generate": every narration clip - handleDeleteBookAudio's action
     *
     * The paragraph passes accept ?fromChapter=<idx> to reset only chapters at
     * or after that index instead of the whole book; the other passes reject it.
     *
     * Doesn't cancel an in-flight run of the same pass, which would set its
     * flag again as it finishes - the Speakers page disables a reset while its
     * pass is running. 200 {"invalidated": n}, n = paragraphs whose audio was
     * deleted (0 for the music/generate resets).
     */
    @POST("api/books/{id}/reset/{pass}")
    suspend fun resetPass(
        @Path("id") id: String,
        @Path("pass") pass: ResetPass,
        @Query("fromChapter") fromChapter: String? = null,
    ): InvalidatedResponseDto

    @GET("api/books/{id}/search")
    suspend fun searchBook(
        @Path("id") id: String,
        @Query("q") q: String? = null,
    ): List<SearchResultDto>

    /**
     * handleListSpeakers reports every speaker recognized in bookID so far -
     * the Narrator plus every attributed character - and how much of each
     * one's audio has actually been generated, so the reader can see which
     * character voices are worth assigning/regenerating before committing to a
     * full multi-voice pass. Speaker attribution and character-voice
     * assignment work the same regardless of book.MultiVoice; this table just
     * reports what would narrate if it's on (see internal/narration.Resolver).
     */
    @GET("api/books/{id}/speakers")
    suspend fun listSpeakers(
        @Path("id") id: String,
    ): List<SpeakerDto>

    /**
     * handleDeleteBookSpeakerData clears every piece of speaker data visible
     * on book's Speakers page: this book's own paragraph attribution (back
     * to "" - Store.ClearBookSpeakers) and, for book's whole series scope
     * (store.SeriesScope - the same scope handleListSpeakers already draws
     * the roster from), every character's identity/Summary, every clone
     * model's voice assignment, and every voice preset auto-created for one
     * of them (+ its cached reference clip) - the Speakers page's own
     * "Delete speaker data" button, for starting completely over. Like
     * handleDeleteCustomVoicePreset, preset deletion here doesn't check
     * whether a preset is also referenced elsewhere (a book's own voice, the
     * default voice, another character happening to share it) first - same
     * no-safety-net convention as deleting one preset manually from the
     * Voices page, just applied in bulk. Best-effort past the first two
     * steps: one character's cleanup failing is logged and skipped rather
     * than aborting the rest, since a bulk delete partially failing and
     * leaving the reader unsure what's left is worse than "cleaned up
     * everything it could, logged what it couldn't."
     */
    @DELETE("api/books/{id}/speakers")
    suspend fun deleteBookSpeakerData(
        @Path("id") id: String,
    ): Unit

    /**
     * handleReattributeSpeaker is the "Auto Split" button's entry point: for a
     * speaker believed not to be a real, distinct individual - a false-positive
     * character attribution's own accidental character row, or the "Unknown"
     * sentinel itself, e.g. after a reader manually renamed/deleted the wrong
     * speaker upstream - it re-judges every one of that speaker's own
     * paragraphs in this book (chapter by chapter, one KindSpeakerReattribution
     * task per chapter, all grouped under one pipeline_auto_split task - see
     * jobs.Manager.EnqueueBulk/RunReattribution) and
     * redistributes them to whichever real character/Narrator/Unknown they
     * actually belong to, using the exact same chapter-wide LLM pass
     * attribution itself already runs (reattributeChapterSpeaker reuses
     * speakerattr.Client.AttributeChapter directly - no second prompt), just
     * with req.Name withheld from "Known characters" and never accepted back
     * as a result for one of its own paragraphs (see reattributeChapterSpeaker's
     * own doc comment).
     *
     * A real character (not Unknown) is marked invalid (store.Character.
     * Invalid) before anything is queued, so the name isn't recreated or
     * reassigned by this or any later attribution pass.
     *
     * Deliberately does NOT delete the character's own identity/voice
     * afterward, even if this run ends up reattributing every one of their
     * paragraphs - unlike handleDeleteCharacter/handleMergeCharacter, which are
     * one synchronous action that knows the outcome immediately, this fans out
     * into several fire-and-forget background tasks with no single moment
     * "reattribution finished" to hang that cleanup off of. A reader can always
     * follow up with the existing Delete button once they see the row is
     * actually empty.
     */
    @POST("api/books/{id}/speakers/reattribute")
    suspend fun reattributeSpeaker(
        @Path("id") id: String,
        @Body body: ReattributeSpeakerRequestDto,
    ): QueuedResponseDto

    /**
     * handleRegenerateVariant re-renders the emotion variant speaker's lines in
     * bookID clone from (whichever preset they currently generate under - see
     * narration.Resolver.ForParagraph): deletes the old take (and any failure
     * marker), resets this book's audio for that speaker's lines in that
     * emotion to pending, and queues the new render right away so it can be
     * previewed. Another book sharing the same preset keeps its already-
     * generated audio until regenerated there. 202 on success.
     */
    @POST("api/books/{id}/speakers/variants/regenerate")
    suspend fun regenerateVariant(
        @Path("id") id: String,
        @Body body: RegenerateVariantRequestDto,
    ): QueuedResponseDto

