     */
    @Streaming
    @GET("api/music-regions/{id}/audio")
    suspend fun getMusicRegionAudio(
        @Path("id") id: String,
    ): ResponseBody

    /**
     * handleRegenerateMusicRegion is POST /api/music-regions/{id}/regenerate -
     * the reader's own per-region "Generate"/"Regenerate" button in
     * annotations view (ChapterSection.MusicRegionBoundary), for a region
     * that's either never been generated yet (still AudioPending, or
     * AudioError from an earlier failed attempt) or one whose already-ready
     * clip the reader just wants re-rolled. Always allowed regardless of
     * current status - store.Store.ResetMusicRegionAudio's own doc comment
     * covers why resetting an already-pending region is harmless.
     *
     * Deletes the old on-disk clip first (best-effort - a region that was
     * never generated has none to remove), then re-dispatches through the
     * same jobs.Manager.MaybeAdvanceChapterMusic path narration completion
     * already uses, and immediately promotes the freshly (re-)queued
     * generation task to TierUrgent - an explicit reader click deserves the
     * same "don't wait behind unrelated background work" treatment
     * EnqueueParagraphRegenerate's own TierUrgent already gives narration.
     * Generation dispatches as one batch task per chapter, not per region (see
     * jobs.Manager.EnqueueMusicGeneration's own doc comment), so promoting
     * "music_gen:"+chapterID by jobs.Manager.PromoteTier directly already
     * covers this region along with whatever else in the chapter is eligible
     * to generate alongside it - there's no narrower per-region task id left
     * to promote instead.
     *
     * Known imperfection: doesn't cascade-invalidate a *following*
     * MusicTransitionContinuation region that was already generated seeded
     * from this region's own (about-to-change) clip - that region's own
     * already-ready audio just keeps playing, now seeded from audio that no
     * longer matches. Regenerating that one too, if the mismatch is audible,
     * is a second manual click away; not worth chasing automatically for a
     * first version of this button.
     */
    @POST("api/music-regions/{id}/regenerate")
    suspend fun regenerateMusicRegion(
        @Path("id") id: String,
    ): QueuedResponseDto

    @Streaming
    @GET("api/paragraphs/{id}/audio")
    suspend fun getAudio(
        @Path("id") id: String,
    ): ResponseBody

    /**
     * handleGetParagraphSFXAudio serves a ready sound-effect clip -
     * handleGetAudio's own counterpart, simpler since SFX audio isn't
     * voice-scoped.
     */
    @Streaming
    @GET("api/paragraphs/{id}/sfx-audio")
    suspend fun getParagraphSFXAudio(
        @Path("id") id: String,
    ): ResponseBody

    /**
     * handleGenerateSFX is the standalone SFX/music test page's own backend
     * surface (see frontend SFXPage.tsx) - handleTestVoiceDesign's own
     * counterpart for this app's generation-only engines: stateless, not
     * attached to any book/chapter/paragraph, returns raw WAV bytes rather
     * than persisting anything. A paragraph wanting to keep a generated
     * sound-effect clip uses the paragraph-scoped POST .../generate-sfx
     * endpoint instead (handleGenerateParagraphSFX, chapters.go) - this one is
     * purely for iterating on a prompt/knob/engine combination before (or
     * without) attaching one to a real paragraph.
     *
     * Dispatched through jobs.Manager.RunSFXPreview (KindSFXPreview, poolSFX)
     * rather than calling s.TTS directly - same "handled as a pooled job"
     * reasoning handleGenerateParagraphSFX's own doc comment gives: this way a
     * standalone test render properly queues/shares poolSFX's own concurrency
     * limit and TTS/LLM-pool mutual exclusion with every other real
     * generation task, instead of racing the worker uncoordinated. One
     * endpoint for every engine, not one per engine: RunSFXPreview doesn't
     * care which of them a given call's own closure actually invokes.
     */
    @Streaming
    @POST("api/sfx/generate")
    suspend fun generateSFX(
        @Body body: GenerateSFXRequestDto,
    ): ResponseBody

    /**
     * handleTestCloneInstruct previews "instructed voice cloning" -
     * breeze_tts's own ability to clone a reference clip *and* apply a style
     * instruction in one call - given an existing voice to clone the reference
     * clip from (BaseID) and a free-form instruction to style it with, without
     * saving anything as a preset first. Backs the voice/character editor's
     * "test with another voice as a base" control - the same thing a reader
     * would use to preview what store.Book.InstructCharacterVoices actually
     * sounds like for one character before turning it on for a whole book.
     */
    @Streaming
    @POST("api/voices/clone-instruct-test")
    suspend fun testCloneInstruct(
        @Body body: TestCloneInstructRequestDto,
    ): ResponseBody

    @GET("api/voices/custom-presets")
    suspend fun listCustomVoicePresets(): List<CustomVoicePresetDto>

    @POST("api/voices/custom-presets")
    suspend fun createCustomVoicePreset(
        @Body body: CustomVoicePresetInputDto,
    ): CustomVoicePresetDto

    @PUT("api/voices/custom-presets/{id}")
    suspend fun updateCustomVoicePreset(
        @Path("id") id: String,
        @Body body: CustomVoicePresetInputDto,
    ): CustomVoicePresetDto

    @DELETE("api/voices/custom-presets/{id}")
    suspend fun deleteCustomVoicePreset(
        @Path("id") id: String,
    ): Unit

    /**
     * handleGetCustomVoiceAudio serves a custom preset's reference clip -
     * what the user will actually hear as their narrator, previewable the
     * same way as a built-in one. Created on first request if it's missing
     * (e.g. the worker was unavailable when this preset was created/edited).
     */
    @Streaming
    @GET("api/voices/custom-presets/{id}/audio")
    suspend fun getCustomVoiceAudio(
        @Path("id") id: String,
    ): ResponseBody

    /**
     * handleRegenerateCustomVoicePreset force re-renders id's reference clip
     * via VoiceDesign from its currently-saved recipe, without touching any of
     * the preset's saved fields - the "Regenerate" button on the Voices page,
     * for retrying after a RefError (tts-service was briefly down, e.g.) or
     * just to pick up a fresh render, without going through Edit -> Save
     * unchanged to get the same effect (see handleUpdateCustomVoicePreset,
     * which always regenerates too, but only as a side effect of saving).
     *
     * Routed through jobs.Manager.RunVoiceProvision (a KindVoiceProvision
     * task, dedup key "regenerate:"+p.ID) rather than calling voicerefs.
     * Regenerate directly, so this shows up on the Jobs dashboard like any
     * other voice work and queues behind - never races - a characterization
     * task for the same identity (see taskBlockedBySpeakerCharacterization);
     * still blocks this handler's own response the same way the direct call
     * used to, so the response shape (voicePresetDTO, synchronous refErr)
     * is unchanged for the frontend.
     *
     * A successful re-render invalidates every already-generated paragraph
     * that was cloned from the old clip: the recipe (instruct/seed/refText)
     * is unchanged by this action, so paragraph_audio's own voice_id (a hash
     * of presetID+instruct+language, not of the clip's actual audio content -
     * see store.VoiceID) never changes and wouldn't otherwise orphan anything,
     * even though the underlying reference audio genuinely did just change -
     * see invalidateAudioForVoicePreset.
     */
    @POST("api/voices/custom-presets/{id}/regenerate")
    suspend fun regenerateCustomVoicePreset(
        @Path("id") id: String,
    ): CustomVoicePresetDto

    /**
     * handleTestCustomVoicePreset synthesizes arbitrary text with an existing
     * custom preset's actual saved voice (its real clone, same path as book
     * narration - not a one-off design-path guess), so the editor can hear how
     * it sounds on something other than the fixed reference line before using
     * it in a book.
     */
    @Streaming
    @POST("api/voices/custom-presets/{id}/test")
    suspend fun testCustomVoicePreset(
        @Path("id") id: String,
        @Body body: TestVoiceRequestDto,
    ): ResponseBody

    /**
     * handleGetDefaultVoice reports the voice new books are created with.
     */
    @GET("api/voices/default")
    suspend fun getDefaultVoice(): VoiceSettingsDto

    /**
     * handleUpdateDefaultVoice sets the voice and clone model new books are
     * created with - "selecting" a voice (or picking the default clone model)
     * on the Voices page. Existing books are unaffected; this only changes
     * what a freshly uploaded book starts with.
     */
    @PUT("api/voices/default")
    suspend fun updateDefaultVoice(
        @Body body: VoiceSettingsUpdateDto,
    ): VoiceSettingsDto

    /**
     * handleTestVoiceDesign previews a voice instruction directly via the
     * worker's stateless VoiceDesign task (no preset_id at all, unlike
     * handleTestCustomVoicePreset/handleTestPreset, which both require one) -
     * the only way to hear an instruct before it's been saved as a preset.
     * When Seed is given, the render is also cached by its exact (instruct,
     * seed, text, language) recipe (see voicerefs.DesignConfigHash) so that
     * creating the preset right after testing it, unchanged, reuses this exact
     * clip instead of paying for a second render.
     *
     * Runs through jobs.Manager.RunVoiceDesignPreview (a real
     * KindVoiceDesignPreview task in poolGeneration) rather than calling
     * s.TTS.Design directly - this used to bypass the job queue entirely, so a
     * "Test" click competed for the ttsworker process uncoordinated with (and
     * outside the concurrency limit protecting) actual paragraph generation.
     * Still blocks and returns the WAV bytes inline, same as before - see
     * RunVoiceDesignPreview's own doc comment for why that shape is kept.
     */
    @Streaming
    @POST("api/voices/design-test")
    suspend fun testVoiceDesign(
        @Body body: TestVoiceDesignRequestDto,
    ): ResponseBody

    @GET("api/voices/languages")
    suspend fun voiceLanguages(): LanguagesResponseDto

    @GET("api/voices/presets")
    suspend fun voicePresets(): VoicePresetsDto

    /**
     * handleGetPresetAudio serves a built-in preset's reference clip, so the
     * user can preview what a curated narrator actually sounds like before
     * picking it. Created on first request if the worker hasn't rendered one
     * yet (e.g. this preset has never been used).
     */
    @Streaming
    @GET("api/voices/presets/{id}/audio")
    suspend fun getPresetAudio(
        @Path("id") id: String,
    ): ResponseBody

    /**
     * handleRegeneratePreset is the built-in-preset equivalent of
     * handleRegenerateCustomVoicePreset - force re-renders id's reference clip
     * via VoiceDesign from its fixed, compiled-in recipe (built-ins are never
     * stored in the DB - see internal/voices' own doc comment - but their
     * rendered reference clip is cached on disk under their own id exactly
     * like a custom preset's, via the same internal/voicerefs). Useful to
     * retry after tts-service was briefly down when a preset's clip was first
     * needed, without waiting for the next arbitrary request that happens to
     * call EnsureFile on it.
     */
    @POST("api/voices/presets/{id}/regenerate")
    suspend fun regeneratePreset(
        @Path("id") id: String,
    ): VoicePresetDto

    /**
     * handleTestPreset is the built-in-preset equivalent of
     * handleTestCustomVoicePreset, so the same "hear it on other text" preview
     * works for curated presets too, not just custom ones.
     */
    @Streaming
    @POST("api/voices/presets/{id}/test")
    suspend fun testPreset(
        @Path("id") id: String,
        @Body body: TestVoiceRequestDto,
    ): ResponseBody

    /**
     * handleVariantAudio serves one emotion variant of a voice preset's
     * reference clip (see voicerefs.EnsureVariantFile) - the Speakers page's
     * per-emotion preview. 404 until it's been rendered.
     */
    @Streaming
    @GET("api/voices/variants/{presetId}/{emotion}/audio")
    suspend fun variantAudio(
        @Path("presetId") presetId: String,
        @Path("emotion") emotion: String,
    ): ResponseBody
}
